function lwModelosDeProyecto(proyecto,villas,catalogo){const cat=catalogo||[];const declarados=(villas||[]).filter((v=>v.proyecto===proyecto));if(declarados.length){const lista=declarados.map((v=>{const c=cat.find((x=>x.id===v.modelo_id))||null;const heredado=v.precio_construccion==null&&c&&c.precio_construccion!=null;return{modelo:v.modelo,modelo_id:v.modelo_id,precio_construccion:heredado?Number(c.precio_construccion):v.precio_construccion!=null?Number(v.precio_construccion):null,moneda:heredado?c.moneda||v.moneda:v.moneda,heredado:!!heredado,ficha:c}}));lista.sort(((a,b)=>String(a.modelo).localeCompare(String(b.modelo))));return{lista:lista,declarados:true}}return{lista:cat.map((c=>({modelo:c.nombre,modelo_id:c.id,precio_construccion:c.precio_construccion!=null?Number(c.precio_construccion):null,moneda:c.moneda,heredado:false,ficha:c}))),declarados:false}}async function lwCargarCatalogoModelos(sb){if(!sb)return{catalogo:[],villas:[],error:"sin conexión"};const[c,v]=await Promise.all([sb.from("modelos").select("id, slug, nombre, dormitorios, banos, villa_m2, terraza_m2, precio_construccion, moneda").eq("activo",true).order("nombre"),sb.from("modelos_villa").select("id, proyecto, proyecto_id, modelo, modelo_id, precio_construccion, moneda")]);if(c.error||v.error)return{catalogo:[],villas:[],error:(c.error||v.error||{}).message||"error"};return{catalogo:c.data||[],villas:v.data||[]}}async function lwDeclaraModelosEnProyecto(sb,proyecto,seleccion,ctx){const c=ctx||{};const villas=(c.villas||[]).filter((v=>v.proyecto===proyecto));const enUso=c.enUso||new Set;const quiere=new Set(seleccion||[]);const altas=[...quiere].filter((id=>!villas.some((v=>v.modelo_id===id))));const bajas=villas.filter((v=>v.modelo_id&&!quiere.has(v.modelo_id)&&!enUso.has(v.modelo)));const rechazadasLocal=villas.filter((v=>v.modelo_id&&!quiere.has(v.modelo_id)&&enUso.has(v.modelo)));if(!altas.length&&!bajas.length)return{ok:true,altas:0,bajas:0,rechazadas:rechazadasLocal};if(!c.proyecto_id)return{ok:false,error:"el proyecto no tiene ficha (falta su id)",altas:0,bajas:0,rechazadas:rechazadasLocal};const r=await sb.rpc("modelos_proyecto_fija",{p_proyecto_id:c.proyecto_id,p_modelos:[...quiere]});if(r.error)return{ok:false,error:r.error.message,altas:0,bajas:0,rechazadas:rechazadasLocal};const d=r.data||{};return{ok:true,altas:d.altas||0,bajas:d.bajas||0,rechazadas:d.rechazadas||[]}}if(typeof module!=="undefined"&&module.exports)module.exports={lwModelosDeProyecto:lwModelosDeProyecto,lwCargarCatalogoModelos:lwCargarCatalogoModelos,lwDeclaraModelosEnProyecto:lwDeclaraModelosEnProyecto};